/**
 * =============================================================================
 * HEALTH CHECK ROUTES
 * =============================================================================
 * Extracted from api-gateway/src/index.ts
 * Provides connector info, gateway health, and aggregated service health.
 * =============================================================================
 */

import { Router, Request, Response } from 'express';
import { ServiceConfig } from '../config/services';
import { ConnectorMeta } from '../middleware/auth';
import { authenticateToken } from '../middleware/auth';
import { query } from '../db';

// The redisService parameter mirrors `import * as redisService from './services/redis'`
// We only require the subset of methods used by these routes.
interface RedisServiceLike {
  getNotificationSettings(key: string): Promise<object | null>;
  getRedisClient(): import('ioredis').default | null;
}

/**
 * Creates an Express Router containing the health-check routes.
 *
 * @param services  – the services record keyed by service name
 * @param redisService – redis service (or compatible object) that exposes `getNotificationSettings`
 */
export function createHealthRoutes(
  services: Record<string, ServiceConfig>,
  redisService: RedisServiceLike,
): Router {
  const router = Router();

  // ---------------------------------------------------------------------------
  // Connector info endpoint for MCP / AI agent connectors
  // ---------------------------------------------------------------------------
  router.get('/api/connector/info', authenticateToken(true), async (req: Request, res: Response) => {
    const meta = (req as any).connectorMeta as ConnectorMeta | undefined;
    if (!meta || req.user?.role !== 'connector') {
      res.status(403).json({ success: false, error: { code: 'FORBIDDEN', message: 'This endpoint is only available for API-key authenticated connectors' } });
      return;
    }

    let connectorConfig: Record<string, unknown> = {};
    try {
      const settingsRaw = await redisService.getNotificationSettings('platform-settings');
      const settings = (settingsRaw || {}) as Record<string, unknown>;
      const integrations = ((settings as any)?.integrations || []) as Array<Record<string, unknown>>;
      const found = integrations.find((i: any) => i.id === meta.connectorId);
      if (found?.config) connectorConfig = found.config as Record<string, unknown>;
    } catch { /* swallow – non-critical */ }

    res.json({
      id: meta.connectorId,
      name: connectorConfig.name || `Connector ${meta.connectorId}`,
      scopes: meta.scopes,
      allowedDocumentTypes: connectorConfig.allowedDocumentTypes || [],
      workflowPolicy: connectorConfig.workflowPolicy || 'enforce',
      rateLimit: meta.rateLimit,
    });
  });

  // ---------------------------------------------------------------------------
  // Gateway health
  // ---------------------------------------------------------------------------
  router.get('/health', (_req: Request, res: Response) => {
    res.json({
      status: 'healthy',
      service: 'api-gateway',
      version: '0.1.0',
      timestamp: new Date().toISOString(),
    });
  });

  // ---------------------------------------------------------------------------
  // Deep readiness check — verifies critical dependencies are reachable.
  //
  // BACKLOG H6: Gateway `/health` was reporting "healthy" even when
  // downstream services were returning 502. That's correct ACA-style
  // semantics (liveness = "the gateway process is running") but operators
  // expected one health endpoint to reflect the platform-as-a-whole state.
  // This endpoint probes the 5 services without which the platform can't
  // serve a single user-facing flow:
  //
  //   - postgres   — every authed read/write
  //   - redis      — sessions, rate limits, settings, audit cache
  //   - auth       — every login + token refresh
  //   - originate  — document CRUD + verify lookup
  //   - anchoring  — chain-first verify path (BACKLOG H6: previously absent
  //                  from the readiness check; verify flows depend on it)
  //
  // Mounted at both `/health/ready` (k8s convention) and `/health/deep`
  // (the name the user-simulated test report referenced).
  // ---------------------------------------------------------------------------
  const deepHealthHandler = async (_req: Request, res: Response): Promise<void> => {
    const CHECK_TIMEOUT = 3000;
    const checks: Record<string, { status: string; latencyMs: number; error?: string; degradedReasons?: unknown }> = {};

    // Helper: run a check with a timeout
    // KS-1101: a check that resolves with an object answered 2xx but reports itself
    // degraded; it is surfaced as `degraded`, never as `up`.
    async function timedCheck(
      name: string,
      fn: () => Promise<void | { degradedReasons?: unknown }>,
    ): Promise<void> {
      const start = Date.now();
      try {
        const result = await Promise.race([
          fn(),
          new Promise<never>((_, reject) =>
            setTimeout(() => reject(new Error('timeout')), CHECK_TIMEOUT),
          ),
        ]);
        checks[name] = result
          ? { status: 'degraded', latencyMs: Date.now() - start, ...(result.degradedReasons !== undefined ? { degradedReasons: result.degradedReasons } : {}) }
          : { status: 'up', latencyMs: Date.now() - start };
      } catch (err: any) {
        checks[name] = {
          status: 'down',
          latencyMs: Date.now() - start,
          error: err?.message || 'Unknown error',
        };
      }
    }

    // Helper: probe a downstream service's /health
    async function probeService(name: string, key: string): Promise<void> {
      await timedCheck(name, async () => {
        const url = services[key]?.url;
        if (!url) throw new Error(`${key} service URL not configured`);
        const controller = new AbortController();
        const timeout = setTimeout(() => controller.abort(), CHECK_TIMEOUT);
        try {
          const resp = await fetch(`${url}/health`, { signal: controller.signal });
          if (!resp.ok) throw new Error(`HTTP ${resp.status}`);
          // KS-1101: anchoring (chain), auth and originate (in-memory fallbacks) answer
          // 200 with `status: 'degraded'`. Read the body so that is not reported as up.
          const body = (await resp.json().catch(() => null)) as { status?: unknown; degradedReasons?: unknown } | null;
          if (body && body.status === 'degraded') return { degradedReasons: body.degradedReasons };
        } finally {
          clearTimeout(timeout);
        }
      });
    }

    await Promise.all([
      timedCheck('postgres', async () => { await query('SELECT 1'); }),
      timedCheck('redis', async () => {
        const client = redisService.getRedisClient();
        if (!client) throw new Error('Redis client not initialised');
        await client.ping();
      }),
      probeService('auth', 'auth'),
      probeService('originate', 'originate'),
      probeService('anchoring', 'anchoring'),
    ]);

    const all = Object.values(checks);
    const downCount = all.filter(c => c.status === 'down').length;
    const degradedCount = all.filter(c => c.status === 'degraded').length;
    // KS-1101 (Wednesday's ruling O-SURFACE, 2026-09-17): readiness counts only `down`.
    // /health/ready is this handler and backs the api-gateway compose healthcheck,
    // mcp-server's service_healthy start and the CI boot wait, so a degraded service
    // is surfaced in the body without failing readiness.
    const ready = downCount === 0;

    res.status(ready ? 200 : 503).json({
      ready,
      status: ready && degradedCount === 0 ? 'healthy' : 'degraded',
      checks,
      summary: {
        total: all.length,
        up: all.length - downCount - degradedCount,
        down: downCount,
        degraded: degradedCount,
      },
      timestamp: new Date().toISOString(),
    });
  };
  router.get('/health/ready', deepHealthHandler);
  router.get('/health/deep', deepHealthHandler);

  // ---------------------------------------------------------------------------
  // Aggregated health check across all services
  //
  // Public exposure of this endpoint is opt-in. The response enumerates every
  // internal service (~20) and their up/down state — it's a free reconnaissance
  // map for an attacker (audit F-04). Set ENABLE_PUBLIC_HEALTH_SERVICES=true
  // ONLY for active platform monitoring; never in production-equivalent envs.
  // The basic /health endpoint above remains public for ACA liveness probes.
  // ---------------------------------------------------------------------------
  router.get('/health/services', async (_req: Request, res: Response) => {
    if (process.env.ENABLE_PUBLIC_HEALTH_SERVICES !== 'true') {
      return res.status(404).json({ success: false, error: { code: 'NOT_FOUND', message: 'Not found' } });
    }
    const serviceHealth: Record<string, { status: string; latency?: number; error?: string }> = {};

    await Promise.all(
      Object.entries(services).map(async ([key, service]) => {
        const start = Date.now();
        try {
          const controller = new AbortController();
          const timeout = setTimeout(() => controller.abort(), 5000);

          const response = await fetch(`${service.url}${service.healthPath}`, {
            signal: controller.signal,
          });

          clearTimeout(timeout);

          serviceHealth[key] = {
            status: response.ok ? 'healthy' : 'unhealthy',
            latency: Date.now() - start,
          };
        } catch (error) {
          serviceHealth[key] = {
            status: 'unreachable',
            latency: Date.now() - start,
            error: error instanceof Error ? error.message : 'Unknown error',
          };
        }
      }),
    );

    const allHealthy = Object.values(serviceHealth).every(s => s.status === 'healthy');

    res.status(allHealthy ? 200 : 503).json({
      status: allHealthy ? 'healthy' : 'degraded',
      gateway: 'healthy',
      services: serviceHealth,
      timestamp: new Date().toISOString(),
    });
  });

  return router;
}

/**
 * KS-480 — connector (sk_ API key) authentication at the gateway.
 *
 * Before KS-480 the validated key's scopes never reached `req.user`
 * (`requireScope` saw `granted: []` and 403'd every scope-gated mount), and no
 * Bearer was attached for the second hop, so downstream Bearer-only services
 * (originate documents, anchoring — pen-test H2) 401'd every connector write.
 * These tests pin the fix: scopes/tenant land on the principal, and the
 * validated key is exchanged for a short-lived connector JWT attached as the
 * Authorization header. Exchange failure leaves the header unset (fail closed
 * downstream) but still authenticates the gateway hop.
 */

import { describe, it, expect, vi, beforeEach } from 'vitest';
import type { Request, Response } from 'express';
import {
  authenticateToken,
  apiKeyCache,
  connectorBearerCache,
} from '../middleware/auth';

const fetchMock = vi.fn();
vi.stubGlobal('fetch', fetchMock);

function makeReq(headers: Record<string, string>): Request {
  return {
    headers,
    get: function (name: string) {
      return (this as any).headers[name?.toLowerCase()];
    },
  } as unknown as Request;
}

function makeRes(): Response & { _status: number; _json: unknown } {
  const res: any = {
    _status: 0,
    _json: null,
    status(code: number) { res._status = code; return res; },
    json(body: unknown) { res._json = body; return res; },
  };
  return res;
}

const VALIDATE_OK = {
  ok: true,
  json: async () => ({
    success: true,
    data: {
      valid: true,
      organizationId: 'org-1',
      tenantId: 'ten-1',
      scopes: ['documents:write', 'anchors:write'],
      connectorId: 'platform-s:ext-1',
      rateLimit: 100,
      rateLimitWindow: 60,
    },
  }),
};

const EXCHANGE_OK = {
  ok: true,
  json: async () => ({ success: true, data: { token: 'connector.jwt.token', expiresIn: 600 } }),
};

describe('KS-480 — sk_ connector auth path', () => {
  beforeEach(() => {
    fetchMock.mockReset();
    apiKeyCache.clear();
    connectorBearerCache.clear();
  });

  it('attaches the key scopes + tenant to req.user and the connector bearer to the request', async () => {
    fetchMock
      .mockResolvedValueOnce(VALIDATE_OK as any) // security validate
      .mockResolvedValueOnce(EXCHANGE_OK as any); // auth connector-token

    const req = makeReq({ 'x-api-key': 'sk_abc' });
    const res = makeRes();
    const next = vi.fn();
    await authenticateToken(true)(req, res, next);

    expect(next).toHaveBeenCalledOnce();
    const user = (req as any).user;
    expect(user.role).toBe('connector');
    expect(user.scopes).toEqual(['documents:write', 'anchors:write']);
    expect(user.tenantId).toBe('ten-1');
    expect(req.headers.authorization).toBe('Bearer connector.jwt.token');
  });

  it('caches the exchanged bearer per key (one exchange for two requests)', async () => {
    fetchMock
      .mockResolvedValueOnce(VALIDATE_OK as any)
      .mockResolvedValueOnce(EXCHANGE_OK as any)
      .mockResolvedValueOnce(VALIDATE_OK as any); // second request re-validates only after cache expiry — validate is also cached, so this may not even fire

    const next = vi.fn();
    await authenticateToken(true)(makeReq({ 'x-api-key': 'sk_abc' }), makeRes(), next);
    const req2 = makeReq({ 'x-api-key': 'sk_abc' });
    await authenticateToken(true)(req2, makeRes(), next);

    expect(req2.headers.authorization).toBe('Bearer connector.jwt.token');
    const exchangeCalls = fetchMock.mock.calls.filter(c => String(c[0]).includes('/internal/connector-token'));
    expect(exchangeCalls).toHaveLength(1);
  });

  it('fails closed on exchange failure: request authenticated, no bearer attached', async () => {
    fetchMock
      .mockResolvedValueOnce(VALIDATE_OK as any)
      .mockResolvedValueOnce({ ok: false, status: 502, json: async () => ({}) } as any);

    const req = makeReq({ 'x-api-key': 'sk_abc' });
    const res = makeRes();
    const next = vi.fn();
    await authenticateToken(true)(req, res, next);

    expect(next).toHaveBeenCalledOnce();
    expect((req as any).user.role).toBe('connector');
    expect(req.headers.authorization).toBeUndefined();
  });

  it('still 401s an invalid key', async () => {
    fetchMock.mockResolvedValueOnce({
      ok: true,
      json: async () => ({ success: true, data: { valid: false, reason: 'Key not found' } }),
    } as any);

    const req = makeReq({ 'x-api-key': 'sk_bad' });
    const res = makeRes();
    const next = vi.fn();
    await authenticateToken(true)(req, res, next);

    expect(next).not.toHaveBeenCalled();
    expect(res._status).toBe(401);
  });
  it('RED KS-1232: GET /api/connector/info answers allowedDocumentTypes [] for a stored "", 0 or false - the three shapes every create refuses', async () => {
    const META = { connectorId: 'platform-s:ext-1', scopes: ['documents:write'], organizationId: 'org-1', tenantId: 'ten-1', rateLimit: 100, rateLimitWindow: 60 };
    apiKeyCache.set('sk_ks1232', { result: META, expiresAt: Date.now() + 60000 });
    connectorBearerCache.set('sk_ks1232', { token: 'connector.jwt.token', expiresAt: Date.now() + 60000 });
    const { createHealthRoutes } = await import('../services/health');
    const answers: unknown[] = [];
    for (const stored of ['', 0, false]) {
      const redisLike = { getNotificationSettings: async () => ({ integrations: [{ id: META.connectorId, config: { allowedDocumentTypes: stored } }] }), getRedisClient: () => null };
      const router = createHealthRoutes({}, redisLike as any);
      const req = Object.assign(makeReq({ 'x-api-key': 'sk_ks1232' }), { method: 'GET', url: '/api/connector/info' });
      const res: any = Object.assign(makeRes(), { setHeader: () => undefined });
      const body = await new Promise<any>((resolve) => { res.json = (b: unknown) => { resolve(b); return res; }; router(req, res, () => resolve({ fellThrough: true })); });
      answers.push([body.id, body.allowedDocumentTypes]);
    }
    expect(answers).toEqual([['platform-s:ext-1', []], ['platform-s:ext-1', []], ['platform-s:ext-1', []]]);
  });
});
